// Filesystem-driven reference refresh and first-link paths through real dialogs.
#include "ActualAuthoringRecording.h"
#include "ResearchSettings.h"
using namespace Research;

int main(int argc,char **argv){
  const auto report=argument(1);wchar_t desktop[256]{};DWORD needed=0;
  if(!GetUserObjectInformationW(GetThreadDesktop(GetCurrentThreadId()),UOI_NAME,desktop,sizeof(desktop),&needed)||QString::fromWCharArray(desktop)!=qEnvironmentVariable("TEXLINE_TEST_DESKTOP")||!QString::fromWCharArray(desktop).startsWith("TeXlineValidation-"))return 2;
  argc=1;QApplication::setAttribute(Qt::AA_DontUseNativeDialogs);TWApp app(argc,argv);app.setQuitOnLastWindowClosed(false);
  QTimer::singleShot(80,&app,[&]{
    const auto folder=QFileInfo(report).absolutePath();QJsonArray checks,frames;int failures=0;
    auto save=[&]{put(report,QJsonDocument(QJsonObject{{"checks",checks},{"failures",failures},{"frames",frames},{"devicePixelRatio",qApp->primaryScreen()->devicePixelRatio()},{"physicalInput",false},{"nativeFileDialog",false}}).toJson());};
    auto check=[&](const QString &name,bool pass){checks.append(QJsonObject{{"name",name},{"passed",pass}});failures+=!pass;save();};
    auto capture=[&](QWidget *widget,const QString &name){QCoreApplication::sendPostedEvents(nullptr,QEvent::LayoutRequest);settle(70);const auto image=widget->grab();const bool saved=image.save(folder+"/"+name+".png");frames.append(QJsonObject{{"file",name+".png"},{"width",widget->width()},{"height",widget->height()},{"devicePixelRatio",image.devicePixelRatio()},{"saved",saved}});check(name+": real widget captured",saved);};
    QTimer watchdog;watchdog.setSingleShot(true);watchdog.setInterval(90000);QObject::connect(&watchdog,&QTimer::timeout,&app,[&]{check("fixture completes without unexpected modal",false);if(auto *d=qobject_cast<QDialog*>(QApplication::activeModalWidget()))d->reject();app.exit(1);});watchdog.start();
    Tw::Settings().setValue("openPDFwithTeX",false);Tw::Settings().setValue("researchFocusMode",false);
    const QSize size(qEnvironmentVariableIsSet("TEXLINE_TEST_HALF")?620:1120,740);
    const QString bare="\\documentclass{article}\n\\begin{document}\nA stable opening.\n\\end{document}\n";
    const QString bibliography="@article{A,title={Alpha study},author={Able, Ada},year={2024}}\n@article{B,title={Beta study},author={Baker, Ben},year={2025}}\n@article{C,title={Gamma study},author={Chen, Chi},year={2026}}\n";
    auto make=[&](const QString &name,const QString &source){const auto path=folder+"/"+name+"/main.tex";put(path,source.toUtf8());auto *w=new TeXDocumentWindow(path);w->resize(size);w->show();QApplication::setActiveWindow(w);w->editor()->setFocus();settle(120);return w;};
    auto open=[&](TeXDocumentWindow *w){w->findChild<QAction*>("researchInsertCitation")->trigger();QPointer<QDialog> d=w->findChild<QDialog*>("researchCitationDialog");check("existing citation command opens the picker",d&&d->isVisible());return d;};
    auto close=[&](TeXDocumentWindow *w){for(auto *d:w->findChildren<QDialog*>())if(d->isVisible())d->reject();settle(60);w->textDoc()->setModified(false);w->close();settle(60);};
    auto cancel=[&](TeXDocumentWindow *w,QPointer<QDialog> d){if(d)key(d,Qt::Key_Escape);check("citation Escape restores focus to the manuscript",waitFor([&]{return (!d||!d->isVisible())&&w->editor()->hasFocus();},3000));};
    QString linked=bare;linked.insert(linked.indexOf("\\begin{document}"),"\\usepackage{natbib}\n");linked.replace("A stable opening.","A stable opening \\citep[2]{C,A}.");linked.insert(linked.indexOf("\\end{document}"),"\\bibliographystyle{plainnat}\n\\bibliography{refs}\n");
    const auto linkedBib=folder+"/watch/refs.bib";put(linkedBib,bibliography.toUtf8());auto *w=make("watch",linked);
    auto c=w->textCursor();c.setPosition(linked.indexOf("citep")+7);w->editor()->setTextCursor(c);auto d=open(w);
    if(d){auto *list=d->findChild<QListWidget*>("researchCitationList");auto *query=d->findChild<QLineEdit*>("researchCitationSearch");auto *locator=d->findChild<QLineEdit*>("researchCitationLocator");auto *style=d->findChild<QComboBox*>("researchCitationStyle");auto *insertion=d->findChild<QLabel*>("researchCitationInsertion");auto *title=d->findChild<QLabel*>("researchCitationTitle");
      check("existing multi-citation loads its original order and current item",waitFor([&]{return list->count()==3;},8000)&&insertion->text()=="\\citep[2]{C,A}"&&list->currentItem()&&list->currentItem()->data(Qt::UserRole).toString()=="C");
      query->setText("study");query->setSelection(1,3);query->setFocus();locator->setText("7--9");style->setCurrentIndex(style->findData("citet"));const auto before=insertion->text();const auto queryCursor=query->cursorPosition(),queryAnchor=query->selectionStart();
      const auto updated=QString(bibliography).replace("Gamma study","Gamma study revised")+"@article{D,title={Delta study added},author={Doe, Dan},year={2027}}\n";
      check("independent bibliography is atomically replaced while picker remains open",put(linkedBib,updated.toUtf8()));
      check("filesystem watcher refreshes metadata without reopening or pressing Insert",waitFor([&]{return list->count()==4&&title->text()=="Gamma study revised";},10000));
      QSet<QString> selected;for(auto *item:list->selectedItems())selected.insert(item->data(Qt::UserRole).toString());
      check("automatic reload preserves query, caret and text selection",query->text()=="study"&&query->cursorPosition()==queryCursor&&query->selectionStart()==queryAnchor&&query->selectedText()=="tud");
      check("automatic reload preserves citation selection order, locator and style",selected==QSet<QString>{"C","A"}&&insertion->text()==before&&before=="\\citet[7--9]{C,A}"&&locator->text()=="7--9"&&style->currentData().toString()=="citet");
      check("metadata refresh keeps the current reference and input focus",list->currentItem()&&list->currentItem()->data(Qt::UserRole).toString()=="C"&&query->hasFocus());capture(d,"citation-watch-preserved");cancel(w,d);
      check("cancelling refreshed citation edits does not touch source or its undo stack",w->textDoc()->editorText()==linked&&!w->textDoc()->isUndoAvailable()&&bytes(w->fileName())==linked.toUtf8());
      d=open(w);if(d){list=d->findChild<QListWidget*>("researchCitationList");check("reopening reads the updated bibliography",waitFor([&]{return list->count()==4;},8000));d->findChild<QLineEdit*>("researchCitationLocator")->setText("7--9");auto *mode=d->findChild<QComboBox*>("researchCitationStyle");mode->setCurrentIndex(mode->findData("citet"));d->findChild<QDialogButtonBox*>("researchCitationButtons")->button(QDialogButtonBox::Ok)->click();check("confirmed citation updates the existing command in place",waitFor([&]{return !d||!d->isVisible();},3000)&&w->textDoc()->editorText()==QString(linked).replace("\\citep[2]{C,A}","\\citet[7--9]{C,A}"));w->editor()->undo();check("updated citation remains one ordinary undo",w->textDoc()->editorText()==linked);}
    }close(w);

    const auto singleBib=folder+"/single/refs.bib";put(singleBib,"@book{only,title={Only local reference},author={Doe, Jane},year={2026}}\n");w=make("single",bare);c=w->textCursor();c.setPosition(bare.indexOf("A stable"));w->editor()->setTextCursor(c);d=open(w);
    if(d){auto *attach=d->findChild<QToolButton*>("researchCitationAttach");check("one unlinked bibliography is offered by its filename",waitFor([&]{return attach->isVisible()&&attach->text()==words("关联 %1…","Link %1…").arg("refs.bib");},8000)&&QFileInfo(attach->toolTip())==QFileInfo(singleBib));capture(d,"citation-one-bibliography");cancel(w,d);check("cancelling a suggestion does not silently link or modify the manuscript",w->textDoc()->editorText()==bare&&bytes(w->fileName())==bare.toUtf8()&&!w->textDoc()->isUndoAvailable());}
    d=open(w);if(d){auto *attach=d->findChild<QToolButton*>("researchCitationAttach");check("the single-file suggestion is available again",waitFor([&]{return attach->isVisible()&&!attach->toolTip().isEmpty();},8000));bool unexpectedPicker=false;QTimer pickerGuard;pickerGuard.setInterval(15);QObject::connect(&pickerGuard,&QTimer::timeout,&app,[&]{if(auto *picker=qobject_cast<QFileDialog*>(QApplication::activeModalWidget())){unexpectedPicker=true;picker->reject();}});pickerGuard.start();attach->click();pickerGuard.stop();auto *list=d->findChild<QListWidget*>("researchCitationList");check("single-file Link reuses the current picker without a file dialog",!unexpectedPicker&&waitFor([&]{return list->count()==1;},8000)&&d->isVisible());
      const auto linkedText=w->textDoc()->editorText();check("explicit Link adds a complete basic bibliography setup once",linkedText.count("\\bibliography{refs}")==1&&linkedText.count("\\bibliographystyle{plain}")==1);
      check("linked reference can be selected and inserted immediately",list->currentItem()&&list->currentItem()->data(Qt::UserRole).toString()=="only"&&d->findChild<QDialogButtonBox*>("researchCitationButtons")->button(QDialogButtonBox::Ok)->isEnabled());d->findChild<QDialogButtonBox*>("researchCitationButtons")->button(QDialogButtonBox::Ok)->click();check("same-window insertion completes after first linking",waitFor([&]{return !d||!d->isVisible();},3000)&&w->textDoc()->editorText().contains("\\cite{only}"));w->editor()->undo();check("citation Undo keeps the preceding explicit link",w->textDoc()->editorText()==linkedText);w->editor()->undo();check("a second Undo restores the unlinked manuscript",w->textDoc()->editorText()==bare);
    }close(w);

    put(folder+"/multiple/one.bib","@book{one,title={First local reference}}\n");put(folder+"/multiple/two.bib","@book{two,title={Second local reference}}\n");w=make("multiple",bare);d=open(w);
    if(d){auto *attach=d->findChild<QToolButton*>("researchCitationAttach");check("multiple unlinked files retain an explicit file choice",waitFor([&]{return attach->isVisible()&&attach->text()==words("关联文献文件…","Link bibliography file…");},8000)&&attach->toolTip().isEmpty());bool pickerSeen=false;QTimer response,timeout;response.setInterval(15);timeout.setSingleShot(true);timeout.setInterval(6000);QObject::connect(&response,&QTimer::timeout,&app,[&]{if(auto *picker=qobject_cast<QFileDialog*>(QApplication::activeModalWidget())){response.stop();pickerSeen=true;key(picker,Qt::Key_Escape);}});QObject::connect(&timeout,&QTimer::timeout,&app,[&]{if(auto *picker=qobject_cast<QFileDialog*>(QApplication::activeModalWidget()))picker->reject();});response.start();timeout.start();attach->click();response.stop();timeout.stop();check("multiple-file Link opens the original chooser and Escape preserves the picker",pickerSeen&&d&&d->isVisible());check("cancelled bibliography choice changes neither source nor disk",w->textDoc()->editorText()==bare&&bytes(w->fileName())==bare.toUtf8()&&!w->textDoc()->isUndoAvailable());cancel(w,d);
    }close(w);watchdog.stop();save();app.exit(failures?1:0);
  });return app.exec();
}
